PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'active', plan_key TEXT NOT NULL DEFAULT 'growth', brand_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tenant_members (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL, display_name TEXT NOT NULL, role TEXT NOT NULL, password_hash TEXT, status TEXT NOT NULL DEFAULT 'invited', last_login_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS demo_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), record_type TEXT NOT NULL, external_id TEXT NOT NULL, data_json TEXT NOT NULL CHECK(json_valid(data_json)), status TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(tenant_id,record_type,external_id));
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_member_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, before_json TEXT, after_json TEXT, ip_hash TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS integration_configs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), provider_key TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'demo', status TEXT NOT NULL DEFAULT 'not_configured', credential_ref TEXT, config_json TEXT NOT NULL DEFAULT '{}', last_sync_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(tenant_id,provider_key));
CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), response_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_demo_records_tenant_type ON demo_records(tenant_id,record_type,status);
CREATE INDEX IF NOT EXISTS idx_demo_records_tenant_updated ON demo_records(tenant_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_date ON audit_log(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_members_tenant_email ON tenant_members(tenant_id,email);
